#!/usr/bin/env python3
"""Check that each checked-in comparator challenge is freshly regenerated.

Every configuration under ``challenges/`` describes one challenge.  A challenge
whose expected file exists is regenerated in a temporary directory and byte
compared; a challenge whose expected file does not exist yet is skipped with a
message, unless its configuration sets ``require_expected``.
"""

from __future__ import annotations

import argparse
import difflib
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Sequence

from challenge_config import (
    ChallengeConfig,
    ChallengeConfigError,
    load_challenges,
)
from assemble_challenge import assemble, assemble_split

# These belong to the scripts, not to the tree under `--root`: the checked tree
# may be a different worktree than the one this script was invoked from.
SCRIPT_DIR = Path(__file__).resolve().parent
EXTRACTOR = SCRIPT_DIR / "extract_closure.lean"
ASSEMBLER = SCRIPT_DIR / "assemble_challenge.py"

# A Lean module header cannot be computed at elaboration time, so the extractor
# is rendered per challenge with its own import block substituted.
IMPORT_BLOCK = re.compile(r"\A(?:[ \t]*\n)*(?:import[ \t]+\S+[^\n]*\n)+")


def run(
    cmd: Sequence[str],
    *,
    cwd: Path,
    stdout: Path | None = None,
    env: dict[str, str] | None = None,
) -> str:
    if stdout is None:
        completed = subprocess.run(
            cmd,
            cwd=cwd,
            check=True,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
        )
        return completed.stdout

    with stdout.open("w", encoding="utf-8") as handle:
        subprocess.run(cmd, cwd=cwd, check=True, text=True, stdout=handle, env=env)
    return ""


def clean_closure_rows(raw_tsv: Path, clean_tsv: Path) -> None:
    rows = []
    for line in raw_tsv.read_text(encoding="utf-8").splitlines():
        if len(line.split("\t")) in (4, 5):
            rows.append(line)
    clean_tsv.write_text("\n".join(rows) + ("\n" if rows else ""), encoding="utf-8")


def read_expected_tree(expected_dir: Path) -> dict[str, bytes]:
    if not expected_dir.is_dir():
        return {}
    return {
        str(path.relative_to(expected_dir)): path.read_bytes()
        for path in sorted(expected_dir.rglob("*.lean"))
    }


def tree_diff(expected: dict[str, bytes], candidate: dict[str, bytes]) -> str:
    out: list[str] = []
    for rel in sorted(set(expected) | set(candidate)):
        old_bytes = expected.get(rel)
        new_bytes = candidate.get(rel)
        if old_bytes == new_bytes:
            continue
        if old_bytes is None:
            out.append(f"--- missing from the checked-in copy: {rel}\n")
            continue
        if new_bytes is None:
            out.append(f"--- no longer generated: {rel}\n")
            continue
        out.extend(
            difflib.unified_diff(
                old_bytes.decode("utf-8", "replace").splitlines(True),
                new_bytes.decode("utf-8", "replace").splitlines(True),
                fromfile=f"checked-in {rel}",
                tofile=f"regenerated {rel}",
            )
        )
    return "".join(out)


def render_extractor(challenge: ChallengeConfig, template: str) -> str:
    """The extractor source with this challenge's import block substituted."""
    body, substitutions = IMPORT_BLOCK.subn(
        lambda _: challenge.import_block(), template, count=1
    )
    if substitutions != 1:
        raise ChallengeConfigError(
            f"{EXTRACTOR} does not start with an import block; cannot render "
            f"challenge {challenge.name!r}"
        )
    return body


def challenge_part(root: Path, relative: str | None) -> bytes:
    """A header or footer file's bytes; empty when unconfigured or absent.

    A challenge under development is generated before its footer exists;
    `missing_challenge_inputs` reports what was left out.  Only `--write`
    generates such a challenge: `check_challenge` refuses to `--update` it, so
    a checked-in expected copy is never written with a part left out.
    """
    if relative is None:
        return b""
    path = root / relative
    return path.read_bytes() if path.exists() else b""


def closure_tsv(root: Path, workdir: Path, challenge: ChallengeConfig) -> Path:
    """Run the rendered extractor and return its cleaned closure TSV."""
    raw_tsv = workdir / "closure.tsv"
    clean_tsv = workdir / "closure.clean.tsv"
    extractor = workdir / "extract_closure.lean"
    extractor.write_text(
        render_extractor(challenge, EXTRACTOR.read_text(encoding="utf-8")),
        encoding="utf-8",
    )

    env = dict(os.environ)
    env.update(challenge.extractor_env())
    run(["lake", "env", "lean", str(extractor)], cwd=root, stdout=raw_tsv, env=env)
    clean_closure_rows(raw_tsv, clean_tsv)
    return clean_tsv


def assemble_candidate(root: Path, workdir: Path, challenge: ChallengeConfig) -> Path:
    body = workdir / "draft.lean"
    candidate = workdir / "Challenge.lean"
    body.write_text(
        assemble(challenge, root, closure_tsv(root, workdir, challenge)),
        encoding="utf-8",
    )

    candidate.write_bytes(
        challenge_part(root, challenge.header)
        + body.read_bytes()
        + b"\n"
        + challenge_part(root, challenge.footer)
    )
    return candidate


def assemble_split_candidate(
    root: Path, workdir: Path, challenge: ChallengeConfig
) -> dict[str, bytes]:
    files = assemble_split(challenge, root, closure_tsv(root, workdir, challenge))
    return {rel: text.encode("utf-8") for rel, text in files.items()}


def write_tree(destination: Path, files: dict[str, bytes]) -> None:
    if destination.exists():
        if destination.is_dir():
            shutil.rmtree(destination)
        else:
            destination.unlink()
    for relative, data in files.items():
        path = destination / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)


def unified_diff(expected: Path, candidate: Path) -> str:
    expected_text = expected.read_text(encoding="utf-8", errors="replace").splitlines(True)
    candidate_text = candidate.read_text(encoding="utf-8", errors="replace").splitlines(True)
    return "".join(
        difflib.unified_diff(
            expected_text,
            candidate_text,
            fromfile=str(expected),
            tofile="regenerated Challenge.lean",
        )
    )


def missing_challenge_inputs(root: Path, challenge: ChallengeConfig) -> list[str]:
    """Header/footer files the configuration names but the tree does not have."""
    return [
        part
        for part in (challenge.header, challenge.footer)
        if part is not None and not (root / part).exists()
    ]


def check_challenge(
    root: Path, challenge: ChallengeConfig, *, update: bool, write: Path | None
) -> int:
    expected = root / challenge.expected

    if not (update or write) and not expected.exists():
        if challenge.require_expected:
            print(
                f"::error::challenge {challenge.name!r}: {challenge.expected} does "
                "not exist; run `python3 scripts/comparator/check_challenge_drift.py "
                f"--root . --challenge {challenge.name} --update`",
                file=sys.stderr,
            )
            return 1
        print(
            f"challenge {challenge.name!r}: no expected file yet "
            f"({challenge.expected}); skipping the drift check"
        )
        return 0

    absent = missing_challenge_inputs(root, challenge)
    if absent and update and write is None:
        # Writing the checked-in copy without a configured part would record a
        # challenge missing those statements; a `require_expected: false`
        # challenge would then stop being skipped and every later drift run
        # would report that hollow copy as current.
        print(
            f"::error::challenge {challenge.name!r}: refusing to update "
            f"{challenge.expected} without {', '.join(absent)} (not in this "
            "tree); the checked-in copy would omit that part of the "
            f"challenge.  Use `--challenge {challenge.name} --write PATH` "
            "while the challenge is still being developed.",
            file=sys.stderr,
        )
        return 1
    if absent:
        print(
            f"challenge {challenge.name!r}: assembling without "
            f"{', '.join(absent)} (not in this tree)",
            file=sys.stderr,
        )

    with tempfile.TemporaryDirectory(prefix=f"comparator-{challenge.name}-") as td:
        if challenge.split:
            candidate_tree = assemble_split_candidate(root, Path(td), challenge)
            if write is not None:
                write_tree(write, candidate_tree)
                print(
                    f"challenge {challenge.name!r}: wrote {write} "
                    f"({len(candidate_tree)} files)"
                )
                return 0
            if update:
                write_tree(expected, candidate_tree)
                print(
                    f"challenge {challenge.name!r}: updated {challenge.expected} "
                    f"({len(candidate_tree)} files)"
                )
                return 0
            expected_tree = read_expected_tree(expected)
            if expected_tree == candidate_tree:
                print(
                    f"challenge {challenge.name!r} is current: {challenge.expected} "
                    f"({len(candidate_tree)} files)"
                )
                return 0
            print(
                f"::error::Comparator challenge {challenge.name!r} regeneration "
                "drift detected.  Run `python3 "
                "scripts/comparator/check_challenge_drift.py --root . "
                f"--challenge {challenge.name} --update` and review the diff.",
                file=sys.stderr,
            )
            print(tree_diff(expected_tree, candidate_tree), file=sys.stderr)
            return 1

        candidate = assemble_candidate(root, Path(td), challenge)
        candidate_bytes = candidate.read_bytes()

        if write is not None:
            write.parent.mkdir(parents=True, exist_ok=True)
            write.write_bytes(candidate_bytes)
            print(f"challenge {challenge.name!r}: wrote {write}")
            return 0

        if update:
            expected.parent.mkdir(parents=True, exist_ok=True)
            expected.write_bytes(candidate_bytes)
            print(f"challenge {challenge.name!r}: updated {challenge.expected}")
            return 0

        if expected.read_bytes() == candidate_bytes:
            print(f"challenge {challenge.name!r} is current: {challenge.expected}")
            return 0

        print(
            f"::error::Comparator challenge {challenge.name!r} regeneration drift "
            "detected.  Run `python3 scripts/comparator/check_challenge_drift.py "
            f"--root . --challenge {challenge.name} --update` and review the "
            "resulting diff.",
            file=sys.stderr,
        )
        print(unified_diff(expected, candidate), file=sys.stderr)
        return 1


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root",
        type=Path,
        default=Path.cwd(),
        help="repository root (default: current directory)",
    )
    parser.add_argument(
        "--challenge",
        action="append",
        metavar="NAME",
        help=(
            "challenge name under challenges/, or a path to a configuration "
            "file; repeatable (default: every configured challenge)"
        ),
    )
    parser.add_argument(
        "--update",
        action="store_true",
        help="rewrite the checked-in generated challenge copy",
    )
    parser.add_argument(
        "--write",
        type=Path,
        metavar="PATH",
        help="write the regenerated challenge to PATH instead of comparing; "
        "requires exactly one --challenge and leaves the expected copy alone",
    )
    args = parser.parse_args(argv)

    try:
        challenges = load_challenges(args.challenge)
    except ChallengeConfigError as exc:
        print(f"::error::{exc}", file=sys.stderr)
        return 1

    if args.write is not None and len(challenges) != 1:
        print(
            "::error::--write needs exactly one --challenge",
            file=sys.stderr,
        )
        return 1
    if not challenges:
        print("::error::no challenge configuration found", file=sys.stderr)
        return 1

    root = args.root.resolve()
    status = 0
    for challenge in challenges:
        status |= check_challenge(
            root, challenge, update=args.update, write=args.write
        )
    return status


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Assemble the body of a comparator `Challenge.lean` from the extractor's TSV.

Input: the TSV produced by ``extract_closure.lean`` (one declaration per row:
name, module path, start line, end line).  For each declaration this script
re-reads its source lines and records the namespace stack active at that
point (tracking ``namespace``/``section``/``end`` lines), orders declarations
topologically (module import rank, then line number), and emits the snippets
grouped under merged namespace blocks with provenance comments.

The elaboration context that the kernel closure cannot see (attribute commands,
``CoeFun`` instances, ``variable``/``open`` blocks) lives in the ``extras`` and
``module_preludes`` tables of the selected challenge configuration under
``challenges/``; the script fails if one of *that challenge's* keys no longer
matches any extracted declaration.  See README.md in this directory for the
full regeneration pipeline.
"""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass
from pathlib import Path

from challenge_config import (
    DEFAULT_CHALLENGE,
    ChallengeConfig,
    ChallengeConfigError,
    Prelude,
    load_challenges,
)


@dataclass(frozen=True)
class DefinitionHole:
    """Exact declaration data for a registered definition value frontier."""

    safety: str


Entry = tuple[str, str, int, int, list[str], DefinitionHole | None]


class StaleContextTables(ValueError):
    """A challenge's ``extras``/``module_preludes`` key matches no declaration."""


class DefinitionFrontierError(ValueError):
    """Definition-hole metadata does not match the selected challenge."""


def source_range_with_context(
    lines: list[str], start: int, end: int
) -> tuple[int, list[str]]:
    """Extend a declaration range to include adjacent scoped context commands."""
    # Lean's source range starts at a declaration's docstring and can omit a
    # declaration-scoped command immediately before it.  Preserve that command:
    # dropping `open scoped Classical in`, for example, removes the local
    # decidability instances needed to re-elaborate the definition body.
    if start > 1 and re.fullmatch(r"open\s+scoped\s+.+\s+in", lines[start - 2].strip()):
        start -= 1
    return start, lines[start - 1 : end]


class Assembler:
    def __init__(
        self,
        repo_root: Path,
        extras: dict[str, list[str]] | None = None,
        module_preludes: dict[str, tuple[Prelude, ...]] | None = None,
        definition_names: tuple[str, ...] = (),
    ) -> None:
        self.repo_root = repo_root
        self.extras = extras or {}
        self.module_preludes = module_preludes or {}
        self.definition_names = set(definition_names)
        self._file_cache: dict[str, list[str]] = {}
        self.out: list[str] = []
        self.cur_ns: list[str] = []
        self.open_prelude: tuple[str, Prelude] | None = None
        self.used_preludes: set[tuple[str, int]] = set()
        self._closure_cache: dict[str, set[str]] = {}
        self.emitted_definition_names: set[str] = set()

    @staticmethod
    def definition_hole_source(
        name: str, source: list[str], hole: DefinitionHole
    ) -> list[str]:
        return replace_definition_value(name, source, hole).splitlines()

    def get_lines(self, path: str) -> list[str]:
        if path not in self._file_cache:
            text = (self.repo_root / path).read_text(encoding="utf-8")
            self._file_cache[path] = text.splitlines()
        return self._file_cache[path]

    def ns_stack_at(self, path: str, line_no: int) -> list[str]:
        """Namespace stack (list of names) active just before 1-indexed line_no."""
        stack: list[tuple[str, str | None]] = []
        for raw in self.get_lines(path)[: line_no - 1]:
            s = raw.strip()
            m = re.match(r"namespace\s+([\w.À-￿']+)", s)
            if m:
                stack.append(("ns", m.group(1)))
                continue
            m = re.match(r"section\s*([\w.À-￿']*)", s)
            if m and s.startswith("section"):
                stack.append(("sec", m.group(1) or None))
                continue
            m = re.match(r"end\s*([\w.À-￿']*)\s*(?:--.*)?$", s)
            if m and s.startswith("end") and stack:
                stack.pop()
        return [n for kind, n in stack if kind == "ns" and n is not None]

    def imports_of(self, path: str) -> list[str]:
        # imports are only legal at the top of a Lean file, so scanning the
        # whole file is safe and robust against comment and module headers
        return [
            m.group(1).replace(".", "/") + ".lean"
            for raw in self.get_lines(path)
            if (
                m := re.match(
                    r"(?:public\s+)?(?:meta\s+)?import(?:\s+all)?\s+([\w.]+)",
                    raw,
                )
            )
        ]

    def local_closure(self, path: str) -> set[str]:
        """All `MIPStarRE/...` modules `path` imports, transitively."""
        cached = self._closure_cache.get(path)
        if cached is not None:
            return cached
        self._closure_cache[path] = set()  # cycle guard
        out: set[str] = set()
        for dep in self.imports_of(path):
            if not dep.startswith("MIPStarRE/"):
                continue
            if not (self.repo_root / dep).exists():
                continue
            out.add(dep)
            out |= self.local_closure(dep)
        self._closure_cache[path] = out
        return out

    def module_ranks(self, mods: set[str]) -> dict[str, int]:
        rank: dict[str, int] = {}

        def visit(p: str, depth: int = 0) -> None:
            if p in rank or depth > 200:
                return
            rank[p] = -1  # in progress
            local = [d for d in self.imports_of(p) if d.startswith("MIPStarRE/")]
            for d in local:
                if rank.get(d) != -1:
                    visit(d, depth + 1)
            rank[p] = max((rank.get(d, 0) for d in local), default=0) + 1

        for p in sorted(mods):
            visit(p)
        return rank

    def switch_ns(self, target: list[str]) -> None:
        common = 0
        while (
            common < min(len(self.cur_ns), len(target))
            and self.cur_ns[common] == target[common]
        ):
            common += 1
        for n in reversed(self.cur_ns[common:]):
            self.out.append(f"end {n}")
        for n in target[common:]:
            self.out.append(f"namespace {n}")
        self.cur_ns = target

    def prelude_for(self, path: str, line: int) -> Prelude | None:
        """The configured scope of ``path`` covering ``line``, if any."""
        for prelude in self.module_preludes.get(path, ()):
            if prelude.covers(line):
                return prelude
        return None

    def close_prelude(self) -> None:
        if self.open_prelude:
            self.switch_ns(list(self.open_prelude[1].namespace))
            self.out.append("end  -- module scope")
            self.open_prelude = None

    def open_prelude_for(self, path: str, prelude: Prelude) -> None:
        self.switch_ns(list(prelude.namespace))
        label = path if prelude.whole_file else f"{path}:{prelude.first}-{prelude.last}"
        self.out.append("")
        self.out.append(f"-- elaboration context of {label}")
        self.out.append("noncomputable section" if prelude.noncomputable else "section")
        self.out.extend(prelude.lines)
        self.open_prelude = (path, prelude)
        self.used_preludes.add((path, prelude.first))

    def emit(self, entries: list[Entry], generated: list[tuple[str, str]]) -> str:
        # compiler-generated declarations (no source range) regenerate
        # identically during elaboration; record them up front as comments so
        # they never interact with namespace or prelude state
        if generated:
            self.out.append("-- Compiler-generated declarations in the closure (no source")
            self.out.append("-- range); they regenerate identically during elaboration:")
            for name, path in generated:
                self.out.append(f"--   {name}  (from {path})")

        emitted_ranges: set[tuple[str, int]] = set()
        # widest range emitted so far per module, to swallow the pieces of a
        # declaration that the closure reports separately
        enclosing: dict[str, tuple[int, int]] = {}
        for name, path, a, b, src, hole in entries:
            if (path, a) in emitted_ranges and hole is None:
                # deriving twins share the range
                continue
            if (path, a) in emitted_ranges:
                raise DefinitionFrontierError(
                    f"registered definition {name!r} shares an already emitted "
                    f"source range {path}:{a}-{b}"
                )
            # a constructor's `.elim`/`.noConfusion`/`.injEq` companion and a
            # `deriving` clause report a range *inside* their inductive's
            # range; emitting those lines on their own is a syntax error, and
            # the inductive command regenerates them anyway
            outer = enclosing.get(path)
            if outer is not None and outer[0] <= a and b <= outer[1] and hole is None:
                continue
            if outer is not None and outer[0] <= a and b <= outer[1]:
                raise DefinitionFrontierError(
                    f"registered definition {name!r} is nested in source range "
                    f"{path}:{outer[0]}-{outer[1]}"
                )
            emitted_ranges.add((path, a))
            enclosing[path] = (a, b)
            prelude = self.prelude_for(path, a)
            if self.open_prelude and self.open_prelude != (path, prelude):
                self.close_prelude()
            if prelude is not None and self.open_prelude is None:
                self.open_prelude_for(path, prelude)
            self.switch_ns(self.ns_stack_at(path, a))
            self.out.append("")
            self.out.append(f"-- source: {path}:{a}-{b}  ({name})")
            if hole is None:
                self.out.extend(src)
            else:
                self.out.extend(self.definition_hole_source(name, src, hole))
                self.emitted_definition_names.add(name)
            self.out.extend(self.extras.get(name, []))
        self.close_prelude()
        self.switch_ns([])
        return "\n".join(self.out)


MIRROR_ROOT = "Challenge"


def mirror_module(path: str) -> str:
    """`MIPStarRE/QPBT/Algebra/Pauli.lean` -> `Challenge.MIPStarRE.QPBT.Algebra.Pauli`."""
    return f"{MIRROR_ROOT}." + path.removesuffix(".lean").replace("/", ".")


def mirror_file(path: str) -> str:
    return f"{MIRROR_ROOT}/" + path


def optional_part_text(root: Path, relative: str | None) -> str:
    """A configured challenge part, or empty text when omitted or absent."""
    if relative is None:
        return ""
    path = root / relative
    return path.read_text(encoding="utf-8") if path.exists() else ""


class SplitAssembler(Assembler):
    """Emit one Mathlib-only challenge module per contributing library module.

    Lean caches an abstracted nested proof and a `match` auxiliary *per module*,
    keyed by the statement and named after the first declaration of that module
    that needs it, and a module only sees the instances its imports declare.  A
    single-file challenge therefore cannot reproduce either name when a library
    fact is needed in two library modules, and it makes every instance visible
    to every declaration.  Mirroring the library's module partition and import
    graph reproduces both by construction.
    """

    def module_body(self, path: str, entries: list[Entry]) -> str:
        self.out = []
        self.cur_ns = []
        self.open_prelude = None
        return self.emit(entries, [])


def minimal_mirror_imports(
    asm: SplitAssembler, path: str, contributing: set[str]
) -> list[str]:
    """Contributing modules `path` imports, with redundant ancestors dropped."""
    reach = {q for q in asm.local_closure(path) if q in contributing}
    minimal = [
        q
        for q in reach
        if not any(r != q and q in asm.local_closure(r) for r in reach)
    ]
    return sorted(minimal)


def assemble_split(
    challenge: ChallengeConfig, root: Path, tsv: Path
) -> dict[str, str]:
    """Return {path relative to the challenge repository: file contents}."""
    asm = SplitAssembler(
        root,
        challenge.extras,
        challenge.module_preludes,
        challenge.definition_names,
    )
    entries, generated = read_entries(asm, tsv)

    rank = asm.module_ranks({e[1] for e in entries})
    entries.sort(key=lambda e: (rank.get(e[1], 999), e[1], e[2]))

    by_module: dict[str, list[Entry]] = {}
    for entry in entries:
        by_module.setdefault(entry[1], []).append(entry)
    contributing = set(by_module)
    ordered = sorted(contributing, key=lambda m: (rank.get(m, 999), m))

    opens = list(challenge.common_opens)
    files: dict[str, str] = {}
    for path in ordered:
        deps = minimal_mirror_imports(asm, path, contributing)
        head = ["import Mathlib"] + [f"import {mirror_module(d)}" for d in deps]
        head += [
            "",
            f"/-! Challenge mirror of `{path}`.",
            "",
            "One challenge module per contributing library module, importing the",
            "mirrors of the library modules this one imports.  The partition is",
            "what makes Lean generate the same auxiliary declarations, under the",
            "same names, as the library does. -/",
            "",
        ]
        head += opens
        body = asm.module_body(path, by_module[path])
        files[mirror_file(path)] = "\n".join(head) + "\n" + body + "\n"

    header = optional_part_text(root, challenge.header)
    footer = optional_part_text(root, challenge.footer)
    part_imports = "\n".join(f"import {mirror_module(m)}" for m in ordered)
    marker = "import Mathlib\n"
    if not header:
        header = marker
    elif marker not in header:
        raise SystemExit("challenge header must start with `import Mathlib`")
    header = header.replace(marker, marker + part_imports + "\n", 1)

    lines: list[str] = []
    if generated:
        lines.append("-- Compiler-generated declarations in the closure (no source")
        lines.append("-- range); they regenerate identically during elaboration:")
        for name, gpath in generated:
            lines.append(f"--   {name}  (from {gpath})")
        lines.append("")
    files["Challenge.lean"] = header + "\n".join(lines) + footer

    check_stale_tables(asm, challenge, entries)
    return files


def read_entries(
    asm: Assembler, tsv: Path
) -> tuple[list[Entry], list[tuple[str, str]]]:
    entries: list[Entry] = []
    generated: list[tuple[str, str]] = []
    for row in tsv.read_text(encoding="utf-8").splitlines():
        if not row or "\t" not in row:
            continue
        columns = row.split("\t", 4)
        if len(columns) not in (4, 5):
            raise DefinitionFrontierError(f"malformed closure row: {row!r}")
        name, path, a, b = columns[:4]
        hole = parse_definition_hole(name, columns[4] if len(columns) == 5 else None)
        if hole is not None and name not in asm.definition_names:
            raise DefinitionFrontierError(
                f"closure marks unregistered definition {name!r} as a value hole"
            )
        if a == "NORANGE":
            if hole is not None:
                raise DefinitionFrontierError(
                    f"registered definition {name!r} has no source range"
                )
            generated.append((name, path))
            continue
        start, end = int(a), int(b)
        start, source = source_range_with_context(asm.get_lines(path), start, end)
        entries.append((name, path, start, end, source, hole))
    return entries, generated


def parse_definition_hole(name: str, raw: str | None) -> DefinitionHole | None:
    if raw is None:
        return None
    markers = {
        "DEF_SAFE": "safe",
        "DEF_UNSAFE": "unsafe",
        "DEF_PARTIAL": "partial",
    }
    safety = markers.get(raw)
    if safety is None:
        raise DefinitionFrontierError(
            f"invalid definition-hole marker for {name!r}: {raw!r}"
        )
    return DefinitionHole(safety=safety)


def replace_definition_value(
    name: str, source: list[str], hole: DefinitionHole
) -> str:
    """Keep a definition command's header and replace its top-level value."""
    text = "\n".join(source)
    declaration_seen = False
    paren_depth = 0
    bracket_depth = 0
    brace_depth = 0
    block_comment_depth = 0
    in_string = False
    escaped = False
    in_line_comment = False
    index = 0

    def at_top_level() -> bool:
        return paren_depth == bracket_depth == brace_depth == 0

    def token_at(token: str) -> bool:
        if not text.startswith(token, index):
            return False
        before = text[index - 1] if index else " "
        after_index = index + len(token)
        after = text[after_index] if after_index < len(text) else " "
        identifier = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'"
        return before not in identifier and after not in identifier

    while index < len(text):
        char = text[index]
        next_char = text[index + 1] if index + 1 < len(text) else ""

        if in_line_comment:
            if char == "\n":
                in_line_comment = False
            index += 1
            continue
        if block_comment_depth:
            if char == "/" and next_char == "-":
                block_comment_depth += 1
                index += 2
            elif char == "-" and next_char == "/":
                block_comment_depth -= 1
                index += 2
            else:
                index += 1
            continue
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            index += 1
            continue
        if char == "-" and next_char == "-":
            in_line_comment = True
            index += 2
            continue
        if char == "/" and next_char == "-":
            block_comment_depth = 1
            index += 2
            continue
        if char == '"':
            in_string = True
            index += 1
            continue

        if char == "(":
            paren_depth += 1
        elif char == ")":
            paren_depth -= 1
        elif char == "[":
            bracket_depth += 1
        elif char == "]":
            bracket_depth -= 1
        elif char == "{":
            brace_depth += 1
        elif char == "}":
            brace_depth -= 1
        elif at_top_level() and not declaration_seen:
            if token_at("def") or token_at("abbrev") or token_at("instance"):
                declaration_seen = True
        elif at_top_level() and declaration_seen:
            if char == ":" and next_char == "=":
                return text[:index].rstrip() + " := by\n  sorry"
            if token_at("where") or char == "|":
                return text[:index].rstrip() + " := by\n  sorry"
        index += 1

    raise DefinitionFrontierError(
        f"could not locate the value of registered definition {name!r} "
        f"(validated safety: {hole.safety})"
    )


def check_stale_tables(
    asm: Assembler, challenge: ChallengeConfig, entries: list[Entry]
) -> None:
    unused_extras = set(challenge.extras) - {name for name, *_ in entries}
    unused_preludes = {
        f"{path}:{scope.first}"
        for path, scopes in challenge.module_preludes.items()
        for scope in scopes
        if (path, scope.first) not in asm.used_preludes
    }
    missing_definitions = set(challenge.definition_names) - asm.emitted_definition_names
    unexpected_definitions = asm.emitted_definition_names - set(challenge.definition_names)
    if unused_extras or unused_preludes or missing_definitions or unexpected_definitions:
        raise StaleContextTables(
            f"stale context tables in {challenge.path} — "
            f"unmatched extras keys: {sorted(unused_extras)}; "
            f"unmatched module_preludes scopes: {sorted(unused_preludes)}; "
            f"missing definition holes: {sorted(missing_definitions)}; "
            f"unexpected definition holes: {sorted(unexpected_definitions)}"
        )


def assemble(challenge: ChallengeConfig, root: Path, tsv: Path) -> str:
    """Assembled body text; raises ``StaleContextTables`` on an unmatched key."""
    asm = Assembler(
        root,
        challenge.extras,
        challenge.module_preludes,
        challenge.definition_names,
    )
    entries, generated = read_entries(asm, tsv)

    rank = asm.module_ranks({e[1] for e in entries})
    entries.sort(key=lambda e: (rank.get(e[1], 999), e[2]))

    body = asm.emit(entries, generated)
    check_stale_tables(asm, challenge, entries)
    return body


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("tsv", type=Path, help="TSV from extract_closure.lean")
    parser.add_argument(
        "--root",
        type=Path,
        default=Path.cwd(),
        help="repository root (default: current directory)",
    )
    parser.add_argument(
        "--challenge",
        default=DEFAULT_CHALLENGE,
        help=(
            "challenge name under challenges/, or a path to a configuration "
            f"file (default: {DEFAULT_CHALLENGE})"
        ),
    )
    parser.add_argument(
        "--split-dir",
        type=Path,
        default=None,
        help="write one challenge module per library module into this directory",
    )
    args = parser.parse_args()

    try:
        challenge = load_challenges([args.challenge])[0]
        if args.split_dir is not None:
            files = assemble_split(challenge, args.root, args.tsv)
            for rel, text in sorted(files.items()):
                dest = args.split_dir / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_text(text, encoding="utf-8")
            print(f"wrote {len(files)} challenge files to {args.split_dir}")
            return 0
        print(assemble(challenge, args.root, args.tsv))
    except (ChallengeConfigError, StaleContextTables, DefinitionFrontierError) as exc:
        print(exc, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Per-challenge configuration for the comparator challenge generator.

A *challenge* is one self-contained `Challenge.lean` file: the Lean modules the
extractor must import, the target theorems whose statement closure it extracts,
the header and footer wrapped around the assembled body, the checked-in
expected copy, and the elaboration-context tables (`extras`,
`module_preludes`) that the kernel closure cannot see.

Configurations live in `scripts/comparator/challenges/<name>.json` and are read
by `extract_closure.lean` (through the environment), `assemble_challenge.py`
and `check_challenge_drift.py`.  See README.md in this directory.

Schema (unknown top-level keys are rejected so typos fail loudly):

```jsonc
{
  "name": "ldt",                       // required, must equal the file stem
  "description": "…",                  // optional, free text
  "imports": ["MIPStarRE.…"],          // required, non-empty
  "targets": ["MIPStarRE.…"],          // required, non-empty; closure roots
  "definition_names": ["MIPStarRE.…"], // optional; values become Challenge holes
  "header": "scripts/…/header.lean",   // optional, null to omit
  "footer": "scripts/…/footer.lean",   // optional, null to omit
  "expected": "scripts/…/Challenge.lean.expected",   // required
  "require_expected": true,            // optional, default true
  "split": false,                      // optional, default false
  "common_opens": ["open scoped …"],  // optional, split-module context
  "extras": {"Decl.Name": ["line"]},   // optional
  "module_preludes": {                 // optional
    // one scope covering the whole module …
    "MIPStarRE/…/Module.lean": {"namespace": ["A", "B"], "lines": ["open …"]},
    // … or several, each covering a line range of it
    "MIPStarRE/…/Other.lean": [
      {"namespace": ["A"], "lines": ["variable …"], "first": 52, "last": 94},
      {"namespace": ["A"], "lines": ["variable …"], "first": 96, "last": 223,
       "noncomputable": true}
    ]
  }
}
```

A module needs one scope per source section whose elaboration context differs:
the self-dual normal basis file, for instance, has a group-algebra section and
a trace-dual section binding the same identifier to different things.  A scope
opened with `noncomputable section` in the source is marked `noncomputable`,
because the definitions inside such a section carry no `noncomputable` keyword
of their own and do not re-elaborate outside one.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any

# Configuration lives next to the scripts that read it, not under the tree
# being checked: `--root` names the library tree, which may be a different
# worktree than the one these scripts were invoked from.
CHALLENGE_DIR = Path(__file__).resolve().parent / "challenges"
DEFAULT_CHALLENGE = "ldt"

# Read by `extract_closure.lean`; comma-separated fully qualified names.
TARGETS_ENV = "MIPSTARRE_COMPARATOR_TARGETS"
DEFINITIONS_ENV = "MIPSTARRE_COMPARATOR_DEFINITIONS"

# `last` of a scope that runs to the end of its module
LAST_LINE = 10**9

_NAME_RE = re.compile(r"[a-z0-9][a-z0-9_-]*\Z")

_KEYS = {
    "name",
    "description",
    "imports",
    "targets",
    "definition_names",
    "header",
    "footer",
    "expected",
    "require_expected",
    "split",
    "common_opens",
    "extras",
    "module_preludes",
}

_PRELUDE_KEYS = {"namespace", "lines", "first", "last", "noncomputable"}


class ChallengeConfigError(ValueError):
    """A challenge configuration is missing a key, or a key has a wrong type."""


@dataclass(frozen=True)
class Prelude:
    """Elaboration context of one source scope of one module.

    The `open`s, `variable`s and `local notation` that the declarations of a
    source section were elaborated under, replayed around the snippets taken
    from lines `first`..`last` of that module.
    """

    namespace: tuple[str, ...]
    lines: tuple[str, ...]
    first: int = 1
    last: int = LAST_LINE
    noncomputable: bool = False

    @property
    def whole_file(self) -> bool:
        return self.first == 1 and self.last == LAST_LINE

    def covers(self, line: int) -> bool:
        return self.first <= line <= self.last


@dataclass(frozen=True)
class ChallengeConfig:
    """One comparator challenge, as configured on disk."""

    name: str
    path: Path
    description: str
    imports: tuple[str, ...]
    targets: tuple[str, ...]
    definition_names: tuple[str, ...]
    header: str | None
    footer: str | None
    expected: str
    require_expected: bool
    split: bool
    common_opens: tuple[str, ...]
    extras: dict[str, list[str]]
    module_preludes: dict[str, tuple[Prelude, ...]]

    def import_block(self) -> str:
        """The extractor's module header for this challenge."""
        return "".join(f"import {module}\n" for module in self.imports)

    def extractor_env(self) -> dict[str, str]:
        """Environment overrides telling the extractor which frontiers to close."""
        env = {TARGETS_ENV: ",".join(self.targets)}
        if self.definition_names:
            env[DEFINITIONS_ENV] = ",".join(self.definition_names)
        return env


def _typed(data: dict[str, Any], key: str, kind: type, where: Path) -> Any:
    if key not in data:
        raise ChallengeConfigError(f"{where}: missing required key {key!r}")
    value = data[key]
    if not isinstance(value, kind):
        raise ChallengeConfigError(
            f"{where}: key {key!r} must be {kind.__name__}, got {type(value).__name__}"
        )
    return value


def _string_list(data: dict[str, Any], key: str, where: Path, *, nonempty: bool) -> tuple[str, ...]:
    value = _typed(data, key, list, where)
    if not all(isinstance(item, str) for item in value):
        raise ChallengeConfigError(f"{where}: key {key!r} must be a list of strings")
    if nonempty and not value:
        raise ChallengeConfigError(f"{where}: key {key!r} must not be empty")
    return tuple(value)


def _optional_string_list(data: dict[str, Any], key: str, where: Path) -> tuple[str, ...]:
    value = data.get(key, [])
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ChallengeConfigError(f"{where}: key {key!r} must be a list of strings")
    if any(not item.strip() for item in value):
        raise ChallengeConfigError(f"{where}: key {key!r} must not contain empty names")
    if len(value) != len(set(value)):
        raise ChallengeConfigError(f"{where}: key {key!r} must not contain duplicates")
    return tuple(value)


def _optional_path(data: dict[str, Any], key: str, where: Path) -> str | None:
    value = data.get(key)
    if value is None:
        return None
    if not isinstance(value, str):
        raise ChallengeConfigError(f"{where}: key {key!r} must be a string or null")
    return value


def _extras(data: dict[str, Any], where: Path) -> dict[str, list[str]]:
    raw = data.get("extras", {})
    if not isinstance(raw, dict):
        raise ChallengeConfigError(f"{where}: key 'extras' must be an object")
    table: dict[str, list[str]] = {}
    for name, lines in raw.items():
        if not isinstance(lines, list) or not all(isinstance(line, str) for line in lines):
            raise ChallengeConfigError(
                f"{where}: extras[{name!r}] must be a list of source lines"
            )
        table[name] = list(lines)
    return table


def _prelude(entry: Any, module: str, where: Path) -> Prelude:
    if not isinstance(entry, dict):
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] must be an object with "
            "'namespace' and 'lines', or a list of such objects"
        )
    unknown = sorted(set(entry) - _PRELUDE_KEYS)
    if unknown:
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] has unknown key(s) {unknown}"
        )
    namespace = entry.get("namespace", [])
    lines = entry.get("lines", [])
    for field, value in (("namespace", namespace), ("lines", lines)):
        if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}][{field!r}] must be a list of strings"
            )
    first = entry.get("first", 1)
    last = entry.get("last", LAST_LINE)
    for field, value in (("first", first), ("last", last)):
        if not isinstance(value, int) or isinstance(value, bool) or value < 1:
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}][{field!r}] must be a positive integer"
            )
    if last < first:
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] has 'last' before 'first'"
        )
    noncomputable = entry.get("noncomputable", False)
    if not isinstance(noncomputable, bool):
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}]['noncomputable'] must be a boolean"
        )
    return Prelude(
        namespace=tuple(namespace),
        lines=tuple(lines),
        first=first,
        last=last,
        noncomputable=noncomputable,
    )


def _module_preludes(data: dict[str, Any], where: Path) -> dict[str, tuple[Prelude, ...]]:
    raw = data.get("module_preludes", {})
    if not isinstance(raw, dict):
        raise ChallengeConfigError(f"{where}: key 'module_preludes' must be an object")
    table: dict[str, tuple[Prelude, ...]] = {}
    for module, entry in raw.items():
        entries = entry if isinstance(entry, list) else [entry]
        scopes = tuple(_prelude(item, module, where) for item in entries)
        if not scopes:
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}] must name at least one scope"
            )
        spans = sorted((scope.first, scope.last) for scope in scopes)
        for (_, earlier_last), (later_first, _) in zip(spans, spans[1:]):
            if later_first <= earlier_last:
                raise ChallengeConfigError(
                    f"{where}: module_preludes[{module!r}] has overlapping scopes; "
                    "one line of a module can only be elaborated in one context"
                )
        table[module] = scopes
    return table


def load_challenge(path: Path) -> ChallengeConfig:
    """Read and validate one challenge configuration file."""
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ChallengeConfigError(f"{path}: no such challenge configuration") from exc
    except json.JSONDecodeError as exc:
        raise ChallengeConfigError(f"{path}: invalid JSON — {exc}") from exc
    if not isinstance(data, dict):
        raise ChallengeConfigError(f"{path}: top level must be an object")

    unknown = sorted(set(data) - _KEYS)
    if unknown:
        raise ChallengeConfigError(f"{path}: unknown key(s) {unknown}")

    name = _typed(data, "name", str, path)
    if not _NAME_RE.match(name):
        raise ChallengeConfigError(
            f"{path}: name {name!r} must match {_NAME_RE.pattern} (it names the CLI selector)"
        )
    if name != path.stem:
        raise ChallengeConfigError(f"{path}: name {name!r} must equal the file stem {path.stem!r}")

    require_expected = data.get("require_expected", True)
    if not isinstance(require_expected, bool):
        raise ChallengeConfigError(f"{path}: key 'require_expected' must be a boolean")

    split = data.get("split", False)
    if not isinstance(split, bool):
        raise ChallengeConfigError(f"{path}: key 'split' must be a boolean")

    common_opens = data.get("common_opens", [])
    if not isinstance(common_opens, list) or not all(
        isinstance(line, str) for line in common_opens
    ):
        raise ChallengeConfigError(
            f"{path}: key 'common_opens' must be a list of strings"
        )

    return ChallengeConfig(
        name=name,
        path=path,
        description=str(data.get("description", "")),
        imports=_string_list(data, "imports", path, nonempty=True),
        targets=_string_list(data, "targets", path, nonempty=True),
        definition_names=_optional_string_list(data, "definition_names", path),
        header=_optional_path(data, "header", path),
        footer=_optional_path(data, "footer", path),
        expected=_typed(data, "expected", str, path),
        require_expected=require_expected,
        split=split,
        common_opens=tuple(common_opens),
        extras=_extras(data, path),
        module_preludes=_module_preludes(data, path),
    )


def challenge_paths(directory: Path | None = None) -> list[Path]:
    """Every configuration file, in a deterministic (file name) order."""
    return sorted((directory or CHALLENGE_DIR).glob("*.json"))


def load_challenges(
    names: list[str] | None = None, directory: Path | None = None
) -> list[ChallengeConfig]:
    """Load the named challenges, or all of them in file-name order."""
    directory = directory or CHALLENGE_DIR
    available = {path.stem: path for path in challenge_paths(directory)}
    if names is None:
        return [load_challenge(path) for _, path in sorted(available.items())]

    selected: list[ChallengeConfig] = []
    for name in names:
        candidate = Path(name)
        if candidate.suffix == ".json" or candidate.parent != Path("."):
            selected.append(load_challenge(candidate))
            continue
        if name not in available:
            raise ChallengeConfigError(
                f"unknown challenge {name!r}; configured: {sorted(available)}"
            )
        selected.append(load_challenge(available[name]))
    return selected

